import Foundation
import XCTest
@testable import SecutgCore

/// PLAN.md 3.40: `vectors-a1q.json`, generated by the Web reference (`src/secutg/config/vectors-a1q.json`), copied
/// byte for byte. Every section is run; a section that goes missing or empty fails rather than passing vacuously.
final class A1QVectorTests: XCTestCase {
    private lazy var vectors: [String: Any] = Vectors.load("vectors-a1q")

    private func section(_ name: String) -> [[String: Any]] {
        let cases = vectors[name] as? [[String: Any]] ?? []
        XCTAssertFalse(cases.isEmpty, "section \(name) is empty")
        return cases
    }

    private func expectedCredentials(_ raw: Any?) -> ApiCredentialRules.Credentials? {
        guard let object = raw as? [String: Any], let id = object["api_id"] as? NSNumber, let hash = object["api_hash"] as? String else { return nil }
        return ApiCredentialRules.Credentials(apiId: id.int32Value, apiHash: hash)
    }

    private func layer(_ raw: Any?) -> ApiCredentialRules.Layer? {
        guard let object = raw as? [String: Any] else { return nil }
        return ApiCredentialRules.Layer(apiId: (object["api_id"] as? NSNumber)?.int32Value, apiHash: object["api_hash"] as? String)
    }

    /// The parse / validate inputs decoded with `JSONDecoder`: `JSONSerialization` (behind `Vectors.load`) drops a
    /// leading U+FEFF from string values, which would turn the "leading BOM is refused" vectors into plain ones.
    private struct ExactInputs: Decodable {
        struct Parse: Decodable { let input: String }
        struct Validate: Decodable { let api_id: String; let api_hash: String }
        let parse: [Parse]
        let validate: [Validate]
    }

    private lazy var exact: ExactInputs? = {
        guard let url = Bundle.module.url(forResource: "vectors-a1q", withExtension: "json", subdirectory: "Vectors"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(ExactInputs.self, from: data)
    }()

    func testFormat() {
        XCTAssertEqual(vectors["format"] as? String, "secutg-a1q-vectors/1")
    }

    func testParse() {
        let inputs = exact?.parse ?? []
        XCTAssertEqual(inputs.count, section("parse").count)
        for (index, item) in section("parse").enumerated() where index < inputs.count {
            let name = item["name"] as? String ?? "?"
            let input = inputs[index].input
            XCTAssertEqual(ApiCredentialRules.parseA1Q(input), expectedCredentials(item["expect"]), name)
        }
    }

    func testValidate() {
        let inputs = exact?.validate ?? []
        XCTAssertEqual(inputs.count, section("validate").count)
        for (index, item) in section("validate").enumerated() where index < inputs.count {
            let name = item["name"] as? String ?? "?"
            let expect = item["expect"] as? [String: Any] ?? [:]
            let result = ApiCredentialRules.validate(apiId: inputs[index].api_id, apiHash: inputs[index].api_hash)
            if expect["ok"] as? Bool == true {
                XCTAssertEqual(result, .ok(expectedCredentials(expect)!), name)
            } else {
                let errors = (expect["errors"] as? [String] ?? []).compactMap(ApiCredentialRules.FieldError.init(rawValue:))
                XCTAssertEqual(result, .invalid(errors), name)
            }
        }
    }

    func testBuild() {
        for item in section("build") {
            let name = item["name"] as? String ?? "?"
            let credentials = ApiCredentialRules.Credentials(apiId: (item["api_id"] as? NSNumber)?.int32Value ?? 0, apiHash: item["api_hash"] as? String ?? "")
            XCTAssertEqual(ApiCredentialRules.buildA1Q(credentials), item["expect"] as? String, name)
            XCTAssertNotNil(ApiCredentialRules.buildA1Q(credentials).flatMap(ApiCredentialRules.parseA1Q), "\(name): round trip")
        }
    }

    func testSource() {
        for item in section("source") {
            let name = item["name"] as? String ?? "?"
            let layers = item["layers"] as? [String: Any] ?? [:]
            let source = ApiCredentialRules.resolveSource(env: layer(layers["env"]), user: layer(layers["user"])?.complete, bundled: layer(layers["bundled"]))
            XCTAssertEqual(source.rawValue, item["expect"] as? String, name)
        }
    }

    func testGate() {
        for item in section("gate") {
            let name = item["name"] as? String ?? "?"
            let input = item["input"] as? [String: Bool] ?? [:]
            let expect = item["expect"] as? [String: Any] ?? [:]
            // `has_session` stays in the vectors to prove it no longer matters (2026-10-02): the rule takes no such input
            let view = ApiCredentialRules.gateView(ApiCredentialRules.GateInput(
                hasEnv: input["has_env"] ?? false, hasUser: input["has_user"] ?? false, hasBundled: input["has_bundled"] ?? false,
                choseBundled: input["chose_bundled"] ?? false))
            if expect["screen"] as? String == "login" {
                XCTAssertEqual(view, .login, name)
            } else {
                XCTAssertEqual(view, .gate(showsBundledOption: expect["shows_bundled_option"] as? Bool ?? false), name)
            }
        }
    }

    func testReminder() {
        let items = section("reminder")
        XCTAssertFalse(items.isEmpty)
        for item in items {
            let name = item["name"] as? String ?? "?"
            let input = item["input"] as? [String: Any] ?? [:]
            let source = ApiCredentialRules.Source(rawValue: input["source"] as? String ?? "")
            XCTAssertNotNil(source, name)
            let due = ApiCredentialRules.shouldRemind(ApiCredentialRules.ReminderInput(
                source: source ?? .none, isLoggedIn: input["logged_in"] as? Bool ?? false,
                laterThisRun: input["later_this_run"] as? Bool ?? false, choseBundled: input["chose_bundled"] as? Bool ?? false))
            XCTAssertEqual(due, item["expect"] as? Bool, name)
        }
    }

    func testRestore() {
        for item in section("restore") {
            let target = ApiCredentialRules.restoreTarget(hasPrevious: item["has_previous"] as? Bool ?? false,
                                                          hasBundledAlternative: item["has_bundled_alternative"] as? Bool ?? false)
            XCTAssertEqual(target.rawValue, item["expect"] as? String, "\(item)")
        }
    }

    func testRejection() {
        for item in section("rejection") {
            let error = item["error"] as? String ?? ""
            XCTAssertEqual(ApiCredentialRules.isRejection(error), item["expect"] as? Bool, error)
        }
        XCTAssertFalse(ApiCredentialRules.isRejection(nil))
    }

    func testSaveNeedsRestart() {
        XCTAssertTrue(ApiCredentialRules.saveNeedsRestart)
    }
}
